// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }
    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        amount = bound(amount, 1, type(uint96).max);
        Attacker attacker = new Attacker(address(c));
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.addToBalance{value: amount}();
        vm.prank(address(attacker));
        c.withdrawBalance();
        assertTrue(attacker.observedBalanceDuringCallback() == 0);
    }
}

contract Attacker {
    Reentrance public target;
    uint256 public observedBalanceDuringCallback;
    bool private __entered;

    constructor(address _target) {
        target = Reentrance(_target);
    }

    receive() external payable {
        if (!__entered) {
            __entered = true;
            observedBalanceDuringCallback = target.getBalance(address(this));
        }
    }
}
